const icon = (code: number, color: string): NerdIcon => ({ char: String.fromCodePoint(code), color });
const index = (rows: [number, Hue, string][]) => {
	const found: Record<string, NerdIcon> = {};
	for (const [code, hue, keys] of rows) {
		const made = icon(code, HUE_ROLES[hue]);
		for (const key of keys.split(" ")) found[key] = made;
	}
	return found;
};

export const file = icon(0xF0214, HUE_ROLES["grey"]);
export const folder = icon(0xE5FF, FOLDER_ROLE);
export const folderOpen = icon(0xE5FE, FOLDER_ROLE);
export const folderEmpty = icon(0xF0256, FOLDER_ROLE);
export const folderEmptyOpen = icon(0xF0DCF, FOLDER_ROLE);
export const byFileName = index(FILE_NAMES);
export const byExtension = index(EXTENSIONS);

/** The icon of a file or folder named `name` (no path), as Neo-tree draws it in LazyVim. */
export function nerdIcon(name: string, { isDirectory = false, open = false, empty = false } = {}): NerdIcon {
	if (isDirectory) return empty ? (open ? folderEmptyOpen : folderEmpty) : open ? folderOpen : folder;
	name = String(name);
	if (Object.hasOwn(byFileName, name)) return byFileName[name];
	// The extension starts after the first dot that is not the name's first character.
	const dot = name.indexOf(".", 1);
	if (dot < 0) return file;
	for (let ext = name.slice(dot + 1).toLowerCase(); ext; ext = ext.includes(".") ? ext.slice(ext.indexOf(".") + 1) : "") {
		if (Object.hasOwn(byExtension, ext)) return byExtension[ext];
	}
	return file;
}
